// Verifica la firma HMAC de Convex (CONVEX_TO_N8N_SECRET) y la antigüedad del timestamp.
const crypto = require('crypto');
const req = $input.first().json;
const headers = req.headers || {};
const ts = headers['x-lendloop-timestamp'];
const sig = String(headers['x-lendloop-signature'] || '');
const payload = req.body && req.body.payload;
const secret = $env.CONVEX_TO_N8N_SECRET;
const fail = (reason) => [{ json: { valid: false, reason } }];

if (!secret) return fail('secret not configured');
if (!ts || !sig || typeof payload !== 'string') return fail('missing signature or payload');
if (!/^\d{9,11}$/.test(ts) || Math.abs(Date.now() / 1000 - Number(ts)) > 300) {
  return fail('stale or invalid timestamp');
}

const expected = crypto.createHmac('sha256', secret).update(`${ts}.${payload}`).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(sig.toLowerCase());
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return fail('bad signature');

let event;
try {
  event = JSON.parse(payload);
} catch {
  return fail('invalid payload');
}
return [{ json: { valid: true, event } }];

// Notificación simulada: se registra en el log de n8n.
// Para enviar un email real, se buscaría el correo en Clerk con recipient.clerkUserId,
// así Convex no necesita guardar correos.
const e = $input.first().json.event;
const notification = {
  channel: 'log',
  event: e.event,
  loanId: e.loanId,
  to: e.recipient.name,
  message: e.message,
  sentAt: new Date().toISOString(),
};
console.log('[LendLoop notification]', JSON.stringify(notification));
return [{ json: { ...notification, idempotencyKey: e.idempotencyKey } }];

// Firma el write-back para Convex con N8N_TO_CONVEX_SECRET.
const crypto = require('crypto');
const secret = $env.N8N_TO_CONVEX_SECRET;
if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not configured');

return $input.all().map(({ json }) => {
  const payload = JSON.stringify({
    loanId: json.loanId,
    type: 'request_notification',
    status: 'sent',
    idempotencyKey: json.idempotencyKey,
    detail: `Notified ${json.to} (${json.event}) via ${json.channel}`,
  });
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${payload}`).digest('hex');
  return { json: { timestamp, signature, body: JSON.stringify({ payload }) } };
});
